from lib import build
R = []
R.append((7212684,
("Pavo en salsa cremosa de poro y perejil", "Jugosa pechuga de pavo magra cocida en una salsa cremosa baja en grasa, repleta de poro y perejil. Una excelente cena entre semana.", "4", "284 g",
 ["2 cucharaditas de aceite de colza", "4 escalopes de pavo, en rebanadas", "2 poros, en rodajas", "3 dientes de ajo, machacados", "una buena pizca de pimienta blanca", "1 cucharadita de mostaza Dijon", "1 cucharada de harina de trigo todo uso", "100 ml de leche descremada", "75 g de queso crema extra ligero", "25 g de perejil, picado"],
 ["Caliente 1 cucharadita del aceite en una sartén y agregue el pavo. Fría 2 minutos por lado para dorar el exterior. Luego páselo a un plato, cubra con papel aluminio y reserve, guardando los jugos que haya soltado.", "Agregue la otra cucharadita de aceite a la misma sartén y añada los poros. Fría suavemente, revolviendo con frecuencia, durante 5 minutos, hasta que empiecen a ablandarse, pero sin dejar que se doren.", "Agregue el ajo, la pimienta blanca, la harina y la mostaza y mezcle bien para que los poros queden cubiertos; luego incorpore poco a poco 200 ml de agua hasta que empiece a espesar.", "Incorpore poco a poco la leche y continúe cocinando y revolviendo hasta que los poros estén suaves. Si la salsa se espesa demasiado, agregue un poco más de leche.", "Regrese a la sartén los escalopes de pavo junto con los jugos que hayan soltado y cocine de 2 a 3 minutos.", "Retire el pavo y agregue el queso crema y el perejil a la salsa; mezcle bien. Vierta sobre los escalopes y sirva con verduras de temporada."],
 ["Puede preparar esta receta con escalopes de cerdo o pechuga de pollo. También queda bien con bacalao o salmón.", "Pruebe a agregar otras hierbas en lugar del perejil, como estragón, cilantro o eneldo.", "Para una versión vegetariana, use 400 g de champiñones enteros en lugar del pavo.", "Porciones de fruta/verdura por porción: 1"], []),
("ديك رومي بصلصة الكراث والبقدونس الكريمية", "صدر ديك رومي خالٍ من الدهن وعصيري، مطهو في صلصة كريمية قليلة الدسم مليئة بالكراث والبقدونس. عشاء رائع في منتصف الأسبوع.", "4", "284 غ",
 ["2 ملعقة صغيرة زيت اللفت (كانولا)", "4 شرائح إسكالوب ديك رومي، مقطعة", "2 كراث، مقطع إلى شرائح", "3 فصوص ثوم، مهروسة", "رشة كبيرة من الفلفل الأبيض", "1 ملعقة صغيرة خردل ديجون", "1 ملعقة كبيرة دقيق عادي", "100 مل حليب خالي الدسم", "75 غ جبن كريمي خفيف جدًا", "25 غ بقدونس، مفروم"],
 ["سخّن 1 ملعقة صغيرة من الزيت في مقلاة وأضف الديك الرومي. قلّبه لمدة دقيقتين على كل جانب ليتحمّر من الخارج. ثم ضعه في طبق، وغطِّه بورق الألمنيوم وضعه جانبًا، مع الاحتفاظ بأي عصارة.", "أضف الملعقة الصغيرة الأخرى من الزيت إلى المقلاة نفسها وأضف الكراث. قلّبه بلطف مع التحريك باستمرار لمدة 5 دقائق حتى يبدأ بالذبول، لكن لا تدعه يتحمّر.", "أضف الثوم والفلفل الأبيض والدقيق والخردل وامزج جيدًا حتى يتغلّف الكراث، ثم أضف 200 مل من الماء تدريجيًا مع التحريك حتى يبدأ بالتكاثف.", "أضف الحليب تدريجيًا مع التحريك وتابع الطهي والتحريك حتى يلين الكراث. إذا أصبحت الصلصة كثيفة جدًا، أضف قليلًا من الحليب.", "أعد شرائح الإسكالوب إلى المقلاة مع أي عصارة خرجت منها واطهها لمدة 2-3 دقائق.", "أخرج الديك الرومي وأضف الجبن الكريمي والبقدونس إلى الصلصة وامزج جيدًا. اسكبها فوق الشرائح وقدّمها مع خضار موسمية."],
 ["يمكنك استخدام هذه الوصفة مع شرائح إسكالوب لحم الخنزير أو صدر الدجاج. وهي لذيذة أيضًا مع سمك القد أو السلمون.", "جرّب إضافة أعشاب مختلفة بدلًا من البقدونس، مثل الطرخون أو الكزبرة أو الشبت.", "للحصول على نسخة نباتية، استخدم 400 غ من الفطر الكامل بدلًا من الديك الرومي.", "حصص الفاكهة/الخضار لكل حصة: 1"], []),
))
R.append((7212729,
("Vasitos de cereza y chocolate", "Esta deliciosa combinación de sabores es un excelente postre más saludable.", "4", "109 g",
 ["225 g de cerezas frescas", "2 cucharadas de edulcorante artificial", "1 cucharadita rasa de fécula de maíz, disuelta en 1 cucharada de agua fría", "100 g de quark o queso suave bajo en grasa", "2 cucharadas de leche descremada", "media cucharadita rasa de extracto de vainilla", "25 g de chocolate oscuro, en trozos", "1 cucharadita colmada de cacao en polvo sin azúcar", "media cucharadita rasa de fécula de maíz, disuelta en media cucharada de agua fría", "1 cucharada rasa de miel de maíz dorada (golden syrup)"],
 ["Parta por la mitad las cerezas frescas y quíteles el hueso, reservando 4 enteras para decorar.", "Póngalas en una olla pequeña con 50 ml de agua y 1 cucharada del edulcorante artificial. Cocine a fuego lento de 3 a 4 minutos, hasta que se ablanden.", "Mezcle la fécula de maíz con el agua fría e incorpórela a las cerezas, revolviendo hasta que espese.", "Retire del fuego y deje enfriar, revolviendo para evitar que se forme una nata.", "En un tazón, bata el quark, la leche descremada, el extracto de vainilla y el resto del edulcorante hasta que quede terso.", "Para la salsa de chocolate, ponga los trozos de chocolate oscuro en una olla y agregue el cacao en polvo sin azúcar, la fécula de maíz disuelta en el agua fría y la miel de maíz dorada. Caliente, revolviendo constantemente, hasta que quede tersa. Deje enfriar, revolviendo para evitar que se forme una nata.", "Reparta todo con una cuchara en vasitos pequeños. Termine cada uno con una cereza. Refrigere y sirva."],
 ["Los arándanos azules o las zarzamoras funcionan igual de bien que las cerezas y son mucho más fáciles de preparar porque no hay que quitarles el hueso.", "También puede usar frambuesas, pero en ese caso reduzca el tiempo de cocción a 2 minutos."], []),
("كؤوس حلوى الكرز والشوكولاتة", "هذا المزيج اللذيذ من النكهات يشكّل حلوى رائعة أكثر صحة.", "4", "109 غ",
 ["225 غ كرز طازج", "2 ملعقة كبيرة محلّي صناعي", "1 ملعقة صغيرة مستوية نشا الذرة، مذابة في 1 ملعقة كبيرة ماء بارد", "100 غ كوارك أو جبن طري قليل الدسم", "2 ملعقة كبيرة حليب خالي الدسم", "نصف ملعقة صغيرة مستوية خلاصة فانيليا", "25 غ شوكولاتة داكنة، مكسرة إلى قطع", "1 ملعقة صغيرة مكوّمة مسحوق كاكاو غير محلّى", "نصف ملعقة صغيرة مستوية نشا الذرة، مذابة في نصف ملعقة كبيرة ماء بارد", "1 ملعقة كبيرة مستوية شراب ذهبي (غولدن سيروب)"],
 ["اقطع الكرز الطازج إلى نصفين وانزع النوى، مع الاحتفاظ بـ 4 حبات كاملة للتزيين.", "ضعه في قدر صغير مع 50 مل من الماء و1 ملعقة كبيرة من المحلّي الصناعي. اتركه على نار هادئة لمدة 3-4 دقائق حتى يلين.", "اخلط نشا الذرة مع الماء البارد وأضفه إلى الكرز مع التحريك حتى يتكاثف.", "ارفعه عن النار واتركه يبرد، مع التحريك لمنع تكوّن طبقة على السطح.", "في وعاء، اخفق الكوارك والحليب الخالي من الدسم وخلاصة الفانيليا وبقية المحلّي حتى يصبح ناعمًا.", "لصنع صلصة الشوكولاتة، ضع قطع الشوكولاتة الداكنة في قدر وأضف مسحوق الكاكاو غير المحلّى ونشا الذرة المذاب في الماء البارد والشراب الذهبي. سخّنها مع التحريك المستمر حتى تصبح ناعمة. اتركها تبرد مع التحريك لمنع تكوّن طبقة على السطح.", "وزّع كل شيء بالملعقة في كؤوس تقديم صغيرة. زيّن كل كأس بحبة كرز. برّدها وقدّمها."],
 ["التوت الأزرق أو التوت الأسود يناسبان بقدر الكرز، وتحضيرهما أسهل بكثير لأنهما لا يحتاجان إلى إزالة النوى.", "يمكنك أيضًا استخدام توت العليق، لكن في هذه الحالة قلّل وقت الطهي إلى دقيقتين."], []),
))
R.append((7215311,
("Pay de pollo, frijoles de media luna y poro", "Este pay dorado cubierto de papa combina pollo con estragón en una salsa de queso, una deliciosa mezcla de sabores para una cena sustanciosa.", "4", "525 g",
 ["1 cucharada de aceite", "2 pechugas de pollo grandes sin hueso ni piel, en cubos", "2 poros, en rodajas", "2 cucharadas de harina", "600 ml de leche semidescremada", "2 cucharadas de estragón fresco, picado", "50 g de queso cheddar añejo, rallado", "1 lata de 420 g de frijoles de media luna (butter beans), escurridos y enjuagados", "750 g de papas harinosas, cocidas y en puré", "10 g de untable a base de aceite vegetal"],
 ["Precaliente el horno a 200 °C (gas 6). Caliente el aceite en una olla, agregue el pollo y los poros y fría de 4 a 5 minutos, hasta que el pollo empiece a dorarse.", "Incorpore la harina y 450 ml de la leche, deje que hierva y revuelva hasta que espese. Agregue el estragón, la mitad del queso y los frijoles de media luna, y sazone bien. Vierta en un recipiente para horno.", "Mezcle el puré de papa, la leche restante, la mantequilla y el queso restante, y coloque sobre la mezcla de pollo con una manga pastelera o con una cuchara.", "Meta el pay al horno y cocine de 20 a 25 minutos, hasta que esté dorado y burbujeante."],
 ["Pruebe a usar camote en lugar de papa común, ya que cuenta como una de sus 5 porciones diarias de fruta y verdura.", "Instrucciones para congelar: Se puede congelar una vez cocinado. Descongele en el refrigerador y recaliente hasta que esté muy caliente por completo.", "Porciones de fruta/verdura por porción: 1"], []),
("فطيرة الدجاج والفاصوليا البيضاء والكراث", "تجمع هذه الفطيرة الذهبية المغطاة بالبطاطس بين الدجاج والطرخون في صلصة الجبن، مزيج شهي من النكهات لعشاء مشبع.", "4", "525 غ",
 ["1 ملعقة كبيرة زيت", "2 صدر دجاج كبير منزوع العظم والجلد، مقطع إلى مكعبات", "2 كراث، مقطع إلى شرائح", "2 ملعقة كبيرة دقيق", "600 مل حليب نصف خالي الدسم", "2 ملعقة كبيرة طرخون طازج، مفروم", "50 غ جبن شيدر معتّق، مبشور", "420 غ علبة فاصوليا بيضاء كبيرة (بتر بينز)، مصفّاة ومشطوفة", "750 غ بطاطس دقيقية القوام، مسلوقة ومهروسة", "10 غ دهن نباتي"],
 ["سخّن الفرن مسبقًا إلى 200° مئوية (درجة الغاز 6). سخّن الزيت في قدر وأضف الدجاج والكراث وقلّبهما لمدة 4-5 دقائق حتى يبدأ الدجاج بالتحمّر.", "أضف الدقيق و450 مل من الحليب، واتركه يغلي مع التحريك حتى يتكاثف. أضف الطرخون ونصف كمية الجبن والفاصوليا البيضاء وتبّل جيدًا. اسكبه في طبق مقاوم للحرارة.", "اخلط البطاطس المهروسة مع بقية الحليب والزبدة وبقية الجبن، وضعها فوق خليط الدجاج بكيس التزيين أو بالملعقة.", "ضع الفطيرة في الفرن واطهها لمدة 20-25 دقيقة حتى تصبح ذهبية وتتفاعل فقاعاتها."],
 ["جرّب استخدام البطاطا الحلوة بدلًا من البطاطس العادية لأنها تُحسب كإحدى حصصك الخمس اليومية من الفاكهة والخضار.", "تعليمات التجميد: يمكن تجميدها بعد الطهي. أذبها في الثلاجة وأعد تسخينها حتى تصبح ساخنة تمامًا من الداخل.", "حصص الفاكهة/الخضار لكل حصة: 1"], []),
))
R.append((7217497,
("Avena horneada", "Si le gusta la avena de la noche anterior, le encantará esta versión recién salida del horno. Un tazón reconfortante de avena horneada es una manera inmejorable de comenzar el día. Esta receta fue seleccionada en colaboración con Slimming World.", "1", "135 g",
 ["40 g de avena para porridge natural", "3 cucharadas rasas de leche descremada", "1 huevo, batido", "½ cucharadita de extracto de vainilla", "¼ de cucharadita de canela molida"],
 ["Precaliente el horno a 200 °C (180 °C con ventilador, gas 6).", "Ponga la avena, la leche, el huevo, la vainilla y la canela en un recipiente pequeño y hondo para horno, que deje espacio para que la mezcla suba al cocinarse. Mezcle bien y hornee en el centro del horno de 20 a 25 minutos, o hasta que esté dorada y firme al tacto.", "Retire del horno, deje enfriar 3 minutos y cubra con el quark o el yogur, la fruta de su elección y una ramita de menta."],
 ["Tenga en cuenta que la información nutricional de esta receta no incluye el quark ni el yogur ni los frutos rojos, ya que son coberturas opcionales.", "Porciones de fruta/verdura por porción: 0"], []),
("شوفان مخبوز", "إذا كنت من محبّي الشوفان المنقوع طوال الليل، فستعشق هذه النسخة الدافئة الخارجة من الفرن. وعاء مريح من الشوفان المخبوز هو أفضل طريقة لبدء اليوم. اختيرت هذه الوصفة بالشراكة مع Slimming World.", "1", "135 غ",
 ["40 غ شوفان للعصيدة عادي", "3 ملعقة كبيرة مستوية حليب خالي الدسم", "1 بيضة، مخفوقة", "½ ملعقة صغيرة خلاصة فانيليا", "¼ ملعقة صغيرة قرفة مطحونة"],
 ["سخّن الفرن مسبقًا إلى 200° مئوية (180° مئوية للفرن بالمروحة، درجة الغاز 6).", "ضع الشوفان والحليب والبيض والفانيليا والقرفة في طبق صغير عميق مقاوم للحرارة يترك مساحة لارتفاع الخليط أثناء الطهي. امزج جيدًا واخبزه في منتصف الفرن لمدة 20-25 دقيقة، أو حتى يصبح ذهبي اللون ومتماسكًا عند اللمس.", "أخرجه من الفرن واتركه يبرد 3 دقائق وزيّنه بالكوارك أو الزبادي والفاكهة التي تختارها وغصن نعناع."],
 ["يُرجى ملاحظة أن المعلومات الغذائية لهذه الوصفة لا تشمل الكوارك أو الزبادي أو التوت لأنها إضافات اختيارية.", "حصص الفاكهة/الخضار لكل حصة: 0"], []),
))
R.append((7217871,
("Lubina al horno con pimientos rojos asados", "Este platillo sencillo y delicioso combina jugosa lubina con un sabor mediterráneo.", "4", "503 g",
 ["600 g de papas peladas, en rodajas finas (de unos 1 cm)", "4 jitomates saladet, sin piel y en cuartos", "2 pimientos rojos y 2 anaranjados, sin semillas y en trozos", "8 dientes de ajo, cada uno cortado en tres", "2 chiles rojos, en rodajas finas", "4 ramitas pequeñas de orégano (o 1 cucharadita de orégano seco)", "4 cucharadas de aceite de oliva", "4 piezas de lubina de 90 g, limpias y recortadas", "50 g de arúgula", "una pizca de pimienta negra"],
 ["Precaliente el horno a 200 °C (gas 6). Ponga las papas en una olla con agua hirviendo durante 7 minutos.", "Escurra las papas y acomódelas en una línea sobre un recipiente grande para asar (como cama para el pescado), dejando un espacio a cada lado.", "Distribuya los jitomates sobre las papas, luego coloque los pimientos rojos y amarillos a ambos lados de las papas y espolvoree con el ajo, los chiles, las ramitas de orégano y el aceite de oliva, reservando 1 cucharada del aceite de oliva. Hornee 30 minutos, girando el recipiente a la mitad del tiempo para que se cocine de manera uniforme.", "Mientras tanto, haga 5 o 6 cortes en cada lado del pescado, frote la piel con el aceite de oliva restante y sazone con sal y pimienta negra. Coloque el pescado sobre las papas.", "Regrese el recipiente al horno y hornee otros 20 a 25 minutos (según el tamaño del pescado), girando de nuevo el recipiente a la mitad, hasta que el pescado esté bien cocido. Sirva con las verduras asadas."],
 ["Esta receta funciona bien con otros pescados enteros, como trucha o besugo.", "Queda estupenda con filetes gruesos de salmón o de cualquier pescado blanco, sobre todo para quienes no gustan de las espinas. Si usa filetes gruesos o filetes en lugar de pescado entero, aumente el tiempo de cocción de las verduras en 10 minutos y reduzca el del pescado a 15 minutos, según su tamaño.", "Es un excelente platillo para una cena con invitados.", "Porciones de fruta/verdura por porción: 3"], []),
("سمك القاروس (سي باس) المخبوز مع الفلفل الأحمر المشوي", "يجمع هذا الطبق البسيط والشهي بين سمك السي باس العصيري ونكهة البحر الأبيض المتوسط.", "4", "503 غ",
 ["600 غ بطاطس مقشرة، مقطعة شرائح رفيعة (حوالي 1 سم)", "4 حبات طماطم برقوقية، منزوعة القشر ومقطعة أرباعًا", "2 فلفل رومي أحمر و2 برتقالي، منزوعة البذور ومقطعة إلى قطع", "8 فصوص ثوم، كل فص مقطوع إلى ثلاث", "2 فلفل أحمر حار، مقطع شرائح رفيعة", "4 أغصان صغيرة من الأوريغانو (أو 1 ملعقة صغيرة مجففة)", "4 ملعقة كبيرة زيت زيتون", "4 سمكات سي باس بوزن 90 غ لكل منها، منظفة ومقصوصة", "50 غ جرجير", "رشة فلفل أسود"],
 ["سخّن الفرن مسبقًا إلى 200° مئوية (درجة الغاز 6). ضع البطاطس في قدر من الماء المغلي لمدة 7 دقائق.", "صفِّ البطاطس ورتّبها في خط واحد في طبق تحميص كبير (كفراش للسمك) مع ترك فراغ على كل جانب.", "وزّع الطماطم فوق البطاطس، ثم ضع الفلفل الرومي الأحمر والأصفر على جانبي البطاطس ورشّ الثوم والفلفل الحار وأغصان الأوريغانو وزيت الزيتون، مع الاحتفاظ بملعقة كبيرة واحدة من زيت الزيتون. اخبزه لمدة 30 دقيقة، مع تدوير الطبق في المنتصف لضمان نضج متساوٍ.", "في هذه الأثناء، اصنع 5-6 شقوق على كل جانب من السمك، وافرك الجلد ببقية زيت الزيتون وتبّل بالملح والفلفل الأسود. ضع السمك فوق البطاطس.", "أعد الطبق إلى الفرن واخبزه 20-25 دقيقة أخرى (حسب حجم السمك)، مع تدوير الطبق في المنتصف مجددًا، حتى ينضج السمك تمامًا. قدّمه مع الخضار المشوية."],
 ["تنجح هذه الوصفة مع أنواع أخرى من الأسماك الكاملة، مثل السلمون المرقط أو الدنيس.", "وهي رائعة مع شرائح السلمون أو أي شرائح سمك أبيض، خاصةً لمن لا يحبون عظام السمك. إذا استخدمت شرائح سميكة أو فيليه بدلًا من السمك الكامل، فزد وقت طهي الخضار 10 دقائق وقلّل وقت طهي السمك إلى 15 دقيقة، حسب حجم السمك.", "إنها طبق رائع لعشاء الضيوف.", "حصص الفاكهة/الخضار لكل حصة: 3"], []),
))
R.append((7219034,
("Callaloo (sopa de cangrejo y espinaca)", "El nombre de esta sopa tan popular es también el del ingrediente principal tradicional, una hoja de tipo espinaca. Pero como el callaloo es bastante difícil de conseguir en el Reino Unido, esta receta usa espinaca como un buen sustituto.", "4", "584 g",
 ["1 cubito de caldo de pollo disuelto en 1.2 L de agua", "1 cebolla pequeña, picada fina", "1 diente de ajo, machacado", "3 cebollines, en rodajas", "una pizca de tomillo seco", "250 g de espinaca fresca, picada en trozos grandes", "2 latas de 170 g de cangrejo, escurrido (peso equivalente: unos 250 g de cangrejo fresco)", "6 cucharadas de leche de coco", "200 g de okra", "pimienta negra recién molida", "unas gotas de Tabasco"],
 ["Ponga el caldo, la cebolla, el ajo, los cebollines y el tomillo en una olla grande.", "Deje que hierva y cocine a fuego lento 10 minutos.", "Agregue la espinaca, el cangrejo, la leche de coco y la okra, y continúe cocinando a fuego lento 10 minutos, hasta que la okra esté tierna. Sazone bien, agregando un poco de Tabasco al gusto."],
 ["Para una versión vegetariana, use caldo de verduras y agregue un pimiento rojo y uno amarillo picados y una lata de 400 g de frijoles rojos.", "Porciones de fruta/verdura por porción: 1"], []),
("كالالو (حساء السلطعون والسبانخ)", "اسم هذا الحساء الشعبي جدًا هو نفسه اسم المكوّن الرئيسي التقليدي، وهو ورقة شبيهة بالسبانخ. ولكن بما أن الكالالو يصعب شراؤه نسبيًا في المملكة المتحدة، تستخدم هذه الوصفة السبانخ كبديل جيد.", "4", "584 غ",
 ["1 مكعب مرق دجاج مذاب في 1.2 لتر ماء", "1 بصلة صغيرة، مفرومة ناعمًا", "1 فص ثوم، مهروس", "3 بصلات خضراء، مقطعة إلى شرائح", "رشة زعتر مجفف", "250 غ سبانخ طازجة، مفرومة فرمًا خشنًا", "2 علبة سلطعون بحجم 170 غ، مصفّاة (ما يعادل وزنًا حوالي 250 غ من السلطعون الطازج)", "6 ملعقة كبيرة حليب جوز الهند", "200 غ بامية", "فلفل أسود مطحون طازجًا", "بضع قطرات من صلصة تاباسكو"],
 ["ضع المرق والبصل والثوم والبصل الأخضر والزعتر في قدر كبير.", "اتركه يغلي ثم اتركه على نار هادئة لمدة 10 دقائق.", "أضف السبانخ والسلطعون وحليب جوز الهند والبامية، وتابع الطهي على نار هادئة لمدة 10 دقائق حتى تلين البامية. تبّل جيدًا مع إضافة قليل من التاباسكو حسب الذوق."],
 ["للحصول على نسخة نباتية، استخدم مرق الخضار فقط وأضف فلفلًا رومي أحمر وأصفر مفرومين وعلبة فاصوليا حمراء بحجم 400 غ.", "حصص الفاكهة/الخضار لكل حصة: 1"], []),
))
R.append((7220139,
("Sopa minestrone sustanciosa", "Una versión vegetariana de la sopa italiana tradicional, con sabor a albahaca y lascas de queso parmesano.", "6", "571 g",
 ["1 cucharada de aceite", "2 dientes de ajo, machacados", "1 cebolla grande, picada", "1 zanahoria grande, picada", "2 tallos de apio, en rodajas finas", "450 g de papas harinosas, picadas", "1.5 L de caldo de verduras", "1 lata de 400 g de tomates picados", "125 g de pasta en formas pequeñas", "200 g de ejotes franceses, partidos por la mitad", "100 g de chícharos congelados", "un cuarto de repollo de Saboya, picado en trozos grandes", "4 cucharadas de perejil fresco, picado", "4 cucharadas de salsa pesto", "pimienta recién molida", "30 g de lascas de queso parmesano fresco"],
 ["Caliente el aceite en una olla grande, agregue el ajo, la cebolla, la zanahoria, el apio y las papas y fría de 3 a 4 minutos, hasta que empiecen a ablandarse sin dorarse.", "Agregue el caldo y los tomates, deje que hierva y cocine a fuego lento 10 minutos. Agregue la pasta, los ejotes, los chícharos y el repollo y continúe cocinando otros 10 minutos, o hasta que la pasta esté cocida.", "Incorpore el perejil y el pesto y sazone bien. Sirva cubierta con lascas de queso parmesano."],
 ["El minestrone es excelente para aprovechar verduras, ya que puede agregar casi cualquiera, por ejemplo chirivía, nabo sueco, papa, calabacitas, pimientos o berenjena.", "Agregue más sabor con 1 cucharadita de orégano y unas hojuelas de chile.", "Hágala vegetariana usando pesto vegetariano y un queso duro vegetariano, como un cheddar fuerte.", "Instrucciones para congelar: Se puede congelar en recipientes pequeños para porciones individuales. Descongele en el microondas y caliente lentamente hasta que esté muy caliente.", "La imagen de esta página es una imagen de archivo y no corresponde a la receta real.", "Porciones de fruta/verdura por porción: 2"], []),
("حساء المينيسترون الغني", "نسخة نباتية من الحساء الإيطالي التقليدي بنكهة الريحان وشرائح جبن البارميزان.", "6", "571 غ",
 ["1 ملعقة كبيرة زيت", "2 فص ثوم، مهروسة", "1 بصلة كبيرة، مفرومة", "1 جزرة كبيرة، مفرومة", "2 ساق كرفس، مقطعة شرائح رفيعة", "450 غ بطاطس دقيقية القوام، مقطعة", "1.5 لتر مرق خضار", "1 علبة بحجم 400 غ من الطماطم المفرومة", "125 غ معكرونة بأشكال صغيرة", "200 غ فاصوليا فرنسية، مقطوعة إلى نصفين", "100 غ بازلاء مجمدة", "ربع ملفوف سافوي، مفروم فرمًا خشنًا", "4 ملعقة كبيرة بقدونس طازج، مفروم", "4 ملعقة كبيرة صلصة بيستو", "فلفل مطحون طازجًا", "30 غ شرائح جبن بارميزان طازج"],
 ["سخّن الزيت في قدر كبير، وأضف الثوم والبصل والجزر والكرفس والبطاطس وقلّبها لمدة 3-4 دقائق حتى تبدأ بالذبول دون أن تتحمّر.", "أضف المرق والطماطم، واتركه يغلي ثم اتركه على نار هادئة لمدة 10 دقائق. أضف المعكرونة والفاصوليا والبازلاء والملفوف وتابع الطهي 10 دقائق أخرى، أو حتى تنضج المعكرونة.", "أضف البقدونس والبيستو وحرّك، وتبّل جيدًا. قدّمه مزينًا بشرائح جبن البارميزان."],
 ["المينيسترون رائع لاستهلاك الخضار المتوفرة، إذ يمكنك إضافة معظم أنواع الخضار، مثل الجزر الأبيض واللفت السويدي والبطاطس والكوسا والفلفل أو الباذنجان.", "أضف مزيدًا من النكهة بملعقة صغيرة من الأوريغانو وقليل من رقائق الفلفل الحار.", "اجعله نباتيًا باستخدام بيستو نباتي وجبن صلب نباتي، مثل جبن الشيدر القوي.", "تعليمات التجميد: يمكن تجميده في أوعية صغيرة لحصص فردية. أذبه في الميكروويف وسخّنه ببطء حتى يصبح ساخنًا جدًا.", "الصورة في هذه الصفحة صورة عامة وليست التقطت للوصفة الفعلية.", "حصص الفاكهة/الخضار لكل حصة: 2"], []),
))
R.append((7221210,
("Pudín navideño", "Prepárese para la Navidad con nuestra versión más saludable de un clásico. Se conserva hasta una semana en el refrigerador.", "6", "82 g",
 ["25 g de pasas sultanas", "25 g de pasas de Corinto", "25 g de pasas", "10 g de cáscara de cítricos confitada mixta", "1 cucharada de mezcla de especias dulces (mixed spice)", "1 cucharada de canela molida", "media cucharadita de clavo molido", "1 cucharadita de jengibre molido", "1 rociada de aceite o media cucharadita de aceite", "20 g de cerezas confitadas, picadas (+ 5 enteras para decorar) 10 g de almendras enteras", "1 plátano pequeño", "1 manzana sin pelar, rallada", "1 zanahoria pequeña, rallada", "50 g de avena molida fina", "30 g de harina integral", "media cucharadita de polvo para hornear", "ralladura de 1 naranja", "ralladura de 1 limón", "10 g de semillas de girasol", "10 g de semillas de calabaza"],
 ["Precaliente el horno a 180 °C (gas 4) y hierva agua en la tetera.", "Ponga todas las frutas secas y las especias en un tazón, mezcle bien y agregue 50 ml de agua hirviendo. Tape y deje reposar 15 minutos.", "Barnice con aceite un molde para pudín de 1 pinta. Acomode en el fondo las cerezas enteras y las almendras enteras.", "En otro tazón, aplaste el plátano y mezcle con la manzana rallada, la zanahoria, la avena, la harina, el polvo para hornear, la ralladura y las semillas.", "Agregue las frutas, las especias y el agua en que se remojaron, mezclando todo bien. Vierta con una cuchara en el molde para pudín.", "Cubra con papel encerado plisado y papel aluminio, y envuelva firmemente sobre el molde.", "Coloque el molde en una charola honda para horno con 5 cm de agua (esto se llama baño María). Hornee 1 hora.", "Retire del baño María y cocine otros 10 minutos. Saque del horno, pero déjelo cubierto. Deje enfriar un poco antes de servir."],
 ["También puede cocer el pudín atando un cordel alrededor del borde para sellarlo. Luego haga un asa de cordel de un lado al otro del molde para poder levantar el pudín. Coloque el molde en una olla con agua que llegue a dos tercios de la altura del molde. Deje que hierva, tape, baje el fuego y cocine suavemente 1.25 horas, cuidando que el agua no se evapore, agregando más agua hirviendo si es necesario.", "Podría usar frutas secas mixtas en lugar de frutas secas por separado. Si no tiene todas las especias, use el doble de mezcla de especias dulces.", "Instrucciones para congelar: Se puede congelar listo para cocinar o ya cocinado. Descongele y luego caliente en el microondas o al vapor para servir.", "Porciones de fruta/verdura por porción: 0"], []),
("بودينغ عيد الميلاد", "استعد لعيد الميلاد مع نسختنا الأكثر صحة من هذا الطبق الكلاسيكي. يمكن حفظه حتى أسبوع في الثلاجة.", "6", "82 غ",
 ["25 غ زبيب سلطانة", "25 غ زبيب كورنثي (كشمش)", "25 غ زبيب", "10 غ قشور حمضيات مشكّلة مسكّرة", "1 ملعقة كبيرة توابل حلوة مشكّلة (ميكسد سبايس)", "1 ملعقة كبيرة قرفة مطحونة", "نصف ملعقة صغيرة قرنفل مطحون", "1 ملعقة صغيرة زنجبيل مطحون", "1 رشة زيت أو نصف ملعقة صغيرة زيت", "20 غ كرز مسكّر، مفروم (+ 5 حبات كاملة للتزيين) 10 غ لوز كامل", "1 موزة صغيرة", "1 تفاحة غير مقشرة، مبشورة", "1 جزرة صغيرة، مبشورة", "50 غ دقيق الشوفان الناعم", "30 غ دقيق القمح الكامل", "نصف ملعقة صغيرة بيكنج باودر", "قشر مبشور من 1 برتقالة", "قشر مبشور من 1 ليمونة", "10 غ بذور دوار الشمس", "10 غ بذور القرع"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (درجة الغاز 4) واغلِ الماء في الغلاية.", "ضع جميع الفواكه المجففة والتوابل في وعاء، وامزجها جيدًا وأضف 50 مل من الماء المغلي. غطِّه واتركه 15 دقيقة.", "ادهن بالزيت وعاء بودينغ سعة 1 باينت. رتّب الكرز الكامل واللوز الكامل في القاع.", "في وعاء منفصل، اهرس الموز وأضف إليه التفاح المبشور والجزر ودقيق الشوفان والدقيق والبيكنج باودر والقشر المبشور والبذور.", "أضف الفواكه والتوابل والماء الذي نُقعت فيه، وامزج كل شيء جيدًا. اسكبه بالملعقة في وعاء البودينغ.", "غطِّه بورق مقاوم للدهن مثني بطيّات وورق ألمنيوم، ولفّه بإحكام فوق الوعاء.", "ضع الوعاء في صينية فرن عميقة فيها 5 سم من الماء (ويسمى ذلك حمّام مائي). اخبزه لمدة ساعة.", "أخرجه من الحمّام المائي واطهه 10 دقائق أخرى. أخرجه من الفرن لكن اتركه مغطى. اتركه يبرد قليلًا قبل التقديم."],
 ["يمكنك أيضًا طهي البودينغ بربط خيط حول حافة الوعاء لإحكام إغلاقه. ثم اصنع مقبضًا من الخيط من جانب إلى آخر من الوعاء لتتمكن من رفع البودينغ. ضع الوعاء في قدر فيه ماء يصل إلى ثلثي ارتفاع الوعاء. اتركه حتى يغلي، وضع الغطاء، وخفّض الحرارة واتركه على نار هادئة بلطف لمدة 1.25 ساعة، مع التأكد من عدم تبخر الماء بإضافة مزيد من الماء المغلي عند الحاجة.", "يمكنك استخدام فواكه مجففة مشكّلة بدلًا من الفواكه المجففة المنفصلة. وإذا لم تتوفر لديك كل التوابل، فاستخدم ضعف كمية التوابل الحلوة المشكّلة.", "تعليمات التجميد: يمكن تجميده جاهزًا للطهي أو بعد طهيه. أذبه ثم سخّنه في الميكروويف أو على البخار للتقديم.", "حصص الفاكهة/الخضار لكل حصة: 0"], []),
))
R.append((7224947,
("Tortitas de papa con salsa de champiñones", "Ideal para aprovechar las papas sobrantes, este platillo saludable puede estar listo en menos de una hora. Enviado por Monika Vecerskyte.", "3", "436 g",
 ["6 papas medianas, bien lavadas", "2 huevos", "½ cucharadita de sal", "hierbas y especias de su elección, al gusto (usamos 1 cucharada de perejil recién picado más una buena pizca de pimienta negra)", "2 cucharaditas de aceite", "2 cebollas grandes, picadas", "2 dientes de ajo, machacados", "250 g de champiñones, en rebanadas (de cualquier tipo)"],
 ["Ralle las papas, tape y reserve.", "En otro tazón, bata los huevos con la sal y las hierbas y especias. Mezcle con las papas ralladas.", "Ponga 1 cucharadita del aceite en una sartén antiadherente a fuego medio-bajo y vierta con una cuchara la mezcla de papa en la sartén, dándole forma de tortitas pequeñas. Cocine por tandas, de 2 a 3 minutos por lado, y reserve hasta que se hayan cocinado todas las tortitas.", "Mientras tanto, ponga el aceite restante en otra sartén y agregue la cebolla, el ajo y los champiñones. Caliente suavemente de 10 a 15 minutos, revolviendo con frecuencia.", "Cuando haya cocinado la última tanda de tortitas, regrese a la sartén las tortitas reservadas durante 1 a 2 minutos para asegurarse de que estén calientes. Sirva con la salsa de champiñones."],
 ["Puede usar 2 cucharaditas de curri en polvo y agregar 50 g de chícharos para hacer tortitas al estilo indio, y servirlas con un raita y/o chutney de mango.", "Para una salsa más cremosa, agregue 2 cucharadas de yogur bajo en grasa a los champiñones.", "Pruebe a usar poros en lugar de cebollas, o use 1 cebolla y 1 poro.", "Porciones de fruta/verdura por porción: 2"], []),
("فطائر البطاطس مع صلصة الفطر", "مثالي لاستهلاك بقايا البطاطس، ويمكن تحضير هذا الطبق الصحي في أقل من ساعة. أرسلته مونيكا فيسيرسكيت.", "3", "436 غ",
 ["6 حبات بطاطس متوسطة الحجم، مغسولة جيدًا", "2 بيضة", "½ ملعقة صغيرة ملح", "أعشاب وتوابل من اختيارك، حسب الذوق (استخدمنا 1 ملعقة كبيرة بقدونس طازج مفروم مع رشة كبيرة من الفلفل الأسود)", "2 ملعقة صغيرة زيت", "2 بصلة كبيرة، مفرومة", "2 فص ثوم، مهروسة", "250 غ فطر، مقطع إلى شرائح (أي نوع)"],
 ["ابشر البطاطس وغطِّها وضعها جانبًا.", "في وعاء منفصل، اخفق البيض مع الملح والأعشاب والتوابل. اخلطه مع البطاطس المبشورة.", "ضع 1 ملعقة صغيرة من الزيت في مقلاة غير لاصقة على نار متوسطة إلى منخفضة، واسكب خليط البطاطس بالملعقة في المقلاة مع تشكيله على هيئة فطائر صغيرة. اطهها على دفعات، لمدة 2-3 دقائق على كل جانب، وضعها جانبًا حتى تنضج جميع الفطائر.", "في هذه الأثناء، ضع بقية الزيت في مقلاة منفصلة وأضف البصل والثوم والفطر. سخّنها بلطف لمدة 10-15 دقيقة مع التحريك باستمرار.", "بعد طهي آخر دفعة من الفطائر، أعد الفطائر المحفوظة إلى المقلاة لمدة 1-2 دقيقة للتأكد من أنها دافئة. قدّمها مع صلصة الفطر."],
 ["يمكنك استخدام 2 ملعقة صغيرة من مسحوق الكاري وإضافة 50 غ من البازلاء لصنع فطائر بالطريقة الهندية، وتقديمها مع الرايتا و/أو مخلل المانجو (تشاتني).", "للحصول على صلصة أكثر كريمية، أضف 2 ملعقة كبيرة من الزبادي قليل الدسم إلى الفطر.", "جرّب استخدام الكراث بدلًا من البصل، أو استخدم 1 بصلة و1 كراث.", "حصص الفاكهة/الخضار لكل حصة: 2"], []),
))
R.append((7227794,
("Pudines invertidos de zarzamora", "Llenos de sabor, estos pudines aprovechan al máximo las zarzamoras.", "6", "139 g",
 ["200 g de zarzamoras", "5 rociadas de aceite en aerosol bajo en grasa", "60 g de untable suave poliinsaturado", "60 g de azúcar refinada", "2 huevos medianos", "120 g de harina blanca con polvo para hornear", "270 g de natilla lista para usar baja en grasa, para servir"],
 ["Ponga las zarzamoras en una olla con 1 cucharada de agua y caliente suavemente de 2 a 3 minutos. Retire del fuego. Engrase seis moldes individuales para pudín con aceite en aerosol bajo en grasa. Reparta la mezcla de zarzamoras entre ellos.", "Ponga el untable, el azúcar refinada, los huevos y la harina en un tazón y bata 1 minuto, hasta que la mezcla quede tersa y cremosa. Reparta entre los moldes y cubra la parte superior con papel aluminio. Colóquelos en una vaporera y cueza al vapor 30 minutos, agregando agua hirviendo si es necesario. Pase un cuchillo por los lados de los moldes y luego desmolde los pudines. Caliente la natilla baja en grasa para servir."],
 ["También puede preparar este pudín con manzanas o peras, u otras frutas como frambuesas o arándanos azules.", "Si no tiene vaporera, hornee los pudines. Colóquelos en una charola para asar con suficiente agua tibia para que llegue a la mitad de los lados y hornee a 180 °C (gas 4) durante 25 minutos.", "Instrucciones para congelar: Descongele y luego caliente en el microondas para servir."], []),
("بودينغ التوت الأسود المقلوب", "هذه البودينغات الغنية بالنكهة تستفيد استفادة كاملة من التوت الأسود.", "6", "139 غ",
 ["200 غ توت أسود", "5 بخّات بخاخ طبخ قليل الدسم", "60 غ دهن طري غني بالدهون غير المشبعة المتعددة", "60 غ سكر ناعم", "2 بيضة متوسطة", "120 غ دقيق أبيض ذاتي الانتفاخ", "270 غ كاسترد جاهز قليل الدسم، للتقديم"],
 ["ضع التوت الأسود في قدر مع 1 ملعقة كبيرة من الماء وسخّنه بلطف لمدة 2-3 دقائق. ارفعه عن النار. ادهن ستة قوالب بودينغ فردية ببخاخ الطبخ قليل الدسم. وزّع خليط التوت الأسود بينها.", "ضع الدهن والسكر الناعم والبيض والدقيق في وعاء خلط واخفقها معًا لمدة دقيقة واحدة حتى يصبح الخليط ناعمًا وكريميًا. وزّعه بين قوالب البودينغ وغطِّ الأسطح بورق الألمنيوم. ضعها في جهاز بخار واطهها على البخار لمدة 30 دقيقة، مع إضافة ماء مغلي عند الحاجة. مرّر سكينًا حول جوانب القوالب ثم اقلب البودينغ. سخّن الكاسترد قليل الدسم للتقديم."],
 ["يمكنك أيضًا تحضير هذا البودينغ بالتفاح أو الكمثرى، أو بفواكه أخرى مثل توت العليق أو التوت الأزرق.", "إذا لم يتوفر لديك جهاز بخار، فاخبز البودينغ بدلًا من ذلك. ضعه في صينية تحميص مع ماء دافئ يكفي ليصل إلى نصف ارتفاع الجوانب تقريبًا، ثم اخبزه على حرارة 180° مئوية (درجة الغاز 4) لمدة 25 دقيقة.", "تعليمات التجميد: أذبه ثم سخّنه في الميكروويف للتقديم."], []),
))
R.append((7231712,
("Chop suey de res", "Este chop suey saludable se prepara con tiras finas de carne de res magra, salteadas con fideos y muchas verduras.", "2", "555 g",
 ["2 cucharaditas de aceite de colza", "200 g de tiras de res magra", "3 cm de jengibre, pelado y picado fino", "4 dientes de ajo, en rodajas finas", "1 cebolla, picada fina", "1 zanahoria, en juliana", "1 pimiento rojo, en rodajas finas", "150 g de brócoli tierno (tenderstem)", "75 g de chícharos chinos", "125 g de fideos integrales secos", "1 cucharada de salsa de ostión", "2 cucharaditas de semillas de ajonjolí"],
 ["Caliente el aceite en un wok o en una olla grande. Agregue las tiras de res, revuelva 1 minuto, luego agregue el jengibre y el ajo y revuelva otro minuto. Retire la carne del wok y reserve.", "Regrese el wok al fuego y agregue la cebolla y la zanahoria. Revuelva 2 minutos, luego agregue el pimiento rojo y el brócoli. Revuelva otros 2 a 3 minutos.", "Agregue de 2 a 3 cucharadas de agua y tape con la tapa de una olla para retener el vapor. Cocine otros 2 minutos.", "Hierva una olla con agua y cocine los fideos secos 4 minutos.", "Regrese la carne al wok, junto con los jugos que haya soltado. Revuelva bien. Agregue los chícharos chinos y los fideos escurridos, y revuelva 2 minutos.", "Por último, incorpore la salsa de ostión y sirva en tazones. Espolvoree con semillas de ajonjolí para servir."],
 ["Para una versión sin gluten, use fideos de arroz.", "Puede usar cerdo, pollo o pavo para este platillo.", "Para una versión vegetariana, use tiras de tofu en lugar de carne de res.", "Porciones de fruta/verdura por porción: 4"], []),
("تشوب سوي باللحم البقري", "يُحضَّر هذا التشوب سوي الصحي من شرائح رفيعة من لحم البقر قليل الدهن، مقلية سريعًا مع النودلز والكثير من الخضار.", "2", "555 غ",
 ["2 ملعقة صغيرة زيت اللفت (كانولا)", "200 غ شرائح لحم بقري قليل الدهن", "3 سم زنجبيل، مقشر ومفروم ناعمًا", "4 فصوص ثوم، مقطعة إلى شرائح رفيعة", "1 بصلة، مفرومة ناعمًا", "1 جزرة، مقطعة أعواد رفيعة", "1 فلفل رومي أحمر، مقطع شرائح رفيعة", "150 غ بروكلي رفيع السيقان (تندرستم)", "75 غ بازلاء سكرية (مانج تو)", "125 غ نودلز القمح الكامل المجففة", "1 ملعقة كبيرة صلصة المحار", "2 ملعقة صغيرة بذور سمسم"],
 ["سخّن الزيت في مقلاة ووك أو قدر كبير. أضف شرائح اللحم، وقلّب لمدة دقيقة، ثم أضف الزنجبيل والثوم وقلّب دقيقة أخرى. أخرج اللحم من الوك وضعه جانبًا.", "أعد الوك إلى النار وأضف البصل والجزر. قلّب لمدة دقيقتين، ثم أضف الفلفل الرومي الأحمر والبروكلي. قلّب دقيقتين إلى 3 دقائق أخرى.", "أضف 2-3 ملاعق كبيرة من الماء، ثم غطِّه بغطاء قدر لحبس البخار. اطهه دقيقتين أخريين.", "اغلِ قدرًا من الماء واسلق النودلز المجففة لمدة 4 دقائق.", "أعد اللحم مع أي عصارة إلى الوك. حرّك جيدًا. أضف البازلاء السكرية والنودلز المصفّاة، ثم قلّب لمدة دقيقتين.", "وأخيرًا، أضف صلصة المحار وحرّك، ثم ضعه في أوعية. رشّ بذور السمسم للتقديم."],
 ["للحصول على نسخة خالية من الغلوتين، استخدم نودلز الأرز.", "يمكنك استخدام لحم الخنزير أو الدجاج أو الديك الرومي لهذا الطبق.", "للحصول على نسخة نباتية، استخدم شرائح التوفو بدلًا من اللحم البقري.", "حصص الفاكهة/الخضار لكل حصة: 4"], []),
))
